<?php
namespace xdecaro\Component\People\Administrator\Service;
defined('_JEXEC') or die;
use Joomla\CMS\Factory;use Joomla\Database\DatabaseInterface;use RuntimeException;
final class DuplicateService{
 public function __construct(private DatabaseInterface $db){}
 public function find(int $limit=100):array{$u=Factory::getApplication()->getIdentity();if(!$u->authorise('core.manage','com_xdecaropeople')&&!$u->authorise('core.admin','com_xdecaropeople'))throw new RuntimeException('Not authorised.',403);$limit=max(1,min(500,$limit));$out=[];$q=$this->db->getQuery(true)->select(['LOWER(TRIM('.$this->db->quoteName('email').')) AS duplicate_key','COUNT(*) AS total'])->from($this->db->quoteName('#__xdecaropeople_people'))->where($this->db->quoteName('state').' >= 0')->where($this->db->quoteName('email').' IS NOT NULL')->where($this->db->quoteName('email')." <> ''")->group('LOWER(TRIM('.$this->db->quoteName('email').'))')->having('COUNT(*) > 1')->order('total DESC');foreach((array)$this->db->setQuery($q,0,$limit)->loadAssocList() as $r)$out[]=['type'=>'email','key'=>$r['duplicate_key'],'count'=>(int)$r['total']];if($u->authorise('people.view_sensitive','com_xdecaropeople')||$u->authorise('core.admin','com_xdecaropeople')){$q=$this->db->getQuery(true)->select(['UPPER(TRIM('.$this->db->quoteName('tax_identifier').')) AS duplicate_key','COUNT(*) AS total'])->from($this->db->quoteName('#__xdecaropeople_people'))->where($this->db->quoteName('state').' >= 0')->where($this->db->quoteName('tax_identifier').' IS NOT NULL')->where($this->db->quoteName('tax_identifier')." <> ''")->group('UPPER(TRIM('.$this->db->quoteName('tax_identifier').'))')->having('COUNT(*) > 1')->order('total DESC');foreach((array)$this->db->setQuery($q,0,$limit)->loadAssocList() as $r)$out[]=['type'=>'tax_identifier','key'=>$r['duplicate_key'],'count'=>(int)$r['total']];}return $out;}
}
